    case .negativeNormal, ./*
*/negativeSubnormal, .positiveZero, .positiveSubnormal, .positiveNormal:
      let digits = String(self)
      return ExprSyntax(FloatLiteralExprSyntax(literal: .floatLiteral(digits)))
    }

  }
}
